<script setup>
import { ref,watch } from 'vue'
import { Dialog,Button } from 'frappe-ui'
import { t as tr } from './i18n.mjs'
import { label } from './reconciliation.mjs'
const props=defineProps({modelValue:Boolean,issue:Object,order:Object,role:String,perform:Function})
const emit=defineEmits(['update:modelValue','open-order'])
const l=(zh,en)=>tr(label(zh,en)),note=ref(''),owner=ref(''),due=ref(''),so=ref(''),factor=ref(1),date=ref(''),error=ref('')
watch(()=>[props.modelValue,props.issue?.id],()=>{note.value=props.issue?.note||'';owner.value=props.issue?.owner||'';due.value=props.issue?.due||'';factor.value=1;date.value='';so.value='';error.value=''})
async function save(action){try{await props.perform(props.issue,{action,note:note.value,owner:owner.value,due:due.value,so:so.value,factor:factor.value,date:date.value});emit('update:modelValue',false)}catch(e){error.value=e.message}}
</script>
<template><Dialog :model-value="modelValue" @update:model-value="emit('update:modelValue',$event)" :options="{title:l('核对与处理','Review & act'),size:'xl'}"><template #body-content><div v-if="issue" class="ops"><div class="ops-review-context"><b>{{tr(issue.title)}}</b><p>{{order?.po}} / {{order?.item}}</p><small>{{tr(issue.detail)}}</small></div><template v-if="role==='buyer'"><div class="ops-form-grid"><label>{{l('责任人','Owner')}}<input v-model="owner"/></label><label>{{l('处理期限','Due date')}}<input v-model="due" type="date"/></label></div><label v-if="issue.kind==='material'" class="ops-form-label">{{l('单位换算：1 工厂单位对应的 PO 单位数量','Conversion: PO units per 1 factory unit')}}<input v-model="factor" type="number" min="0.000001" step="any"/><small>1 {{order?.soUnit}} = {{factor}} {{order?.unit}}</small></label><label v-if="issue.kind==='reference'" class="ops-form-label">{{l('已核实的 SO 引用','Verified SO reference')}}<input v-model="so" placeholder="DEMO-SO-NEW"/></label><label v-if="issue.kind==='delivery'" class="ops-form-label">{{l('新的承诺发运日期','New promised dispatch date')}}<input v-model="date" type="date"/></label><p v-if="issue.kind==='price'" class="ops-note">{{l('确认当前 SAP 价格为正式采购计价后，该行才纳入已确认货值；本操作不改写 SAP 价格。','Confirm the current SAP price as the formal PO price to include this line in confirmed value. This does not change SAP prices.')}}</p><p v-if="issue.kind==='material'" class="ops-note">{{l('确认仅适用于本订单行的双方料号和单位；原始编码变化后会重新核对。','Confirmation applies to this order line and this exact code/unit pair. Changes trigger a new review.')}}</p><p v-if="['shipment','quantity'].includes(issue.kind)" class="ops-note">{{l('此类差异须由匹配的源数据消除。可先分派跟进，不能仅填写备注就关闭。','This discrepancy requires matching source facts. Assign follow-up now; notes alone cannot close it.')}}</p><label class="ops-form-label">{{l('处理记录／确认依据（必填）','Action / confirmation evidence (required)')}}<textarea v-model="note" rows="3" :placeholder="l('写明核实对象、结果与下一步','Record what was checked, the result and next action')"></textarea></label></template><p v-else>{{l('此项由内部采购确认。你可以打开订单补充沟通和交付信息。','Internal purchasing confirms this issue. Open the order to add comments and delivery information.')}}</p><p v-if="error" class="ops-error" role="alert">{{error}}</p></div></template><template #actions><div class="modal-actions"><Button variant="outline" @click="emit('update:modelValue',false)">{{tr('取消')}}</Button><Button v-if="issue?.kind==='logistics'" variant="outline" @click="emit('open-order',order,'logistics');emit('update:modelValue',false)">{{l('维护物流与延期','Edit logistics & delay')}}</Button><Button v-if="role==='buyer'" variant="outline" @click="save('followup')">{{l('保存跟进','Save follow-up')}}</Button><Button v-if="role==='buyer'&&['material','reference','price','delivery'].includes(issue?.kind)" variant="solid" class="primary" @click="save('confirm')">{{l('确认并重新核对','Confirm & recheck')}}</Button><Button v-if="role!=='buyer'" variant="solid" class="primary" @click="emit('open-order',order,'activity');emit('update:modelValue',false)">{{l('打开订单','Open order')}}</Button></div></template></Dialog></template>
